package com.mengzhihua.crm.sales.controller;
import com.mengzhihua.crm.common.*;import com.mengzhihua.crm.sales.entity.Contact;import com.mengzhihua.crm.sales.service.ContactService;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/contacts")public class ContactController{private final ContactService s;public ContactController(ContactService x){s=x;}@GetMapping public Result<PageResult<Contact>> list(@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="10")int size,@RequestParam(required=false)String keyword,@RequestParam(required=false)Long accountId){return Result.ok(s.list(page,size,keyword,accountId));}@GetMapping("/{id}")public Result<Contact> get(@PathVariable Long id){return Result.ok(s.get(id));}@PostMapping public Result<Contact> add(@RequestBody Contact x){return Result.ok(s.save(x));}@PutMapping("/{id}")public Result<Contact> edit(@PathVariable Long id,@RequestBody Contact x){x.setId(id);return Result.ok(s.save(x));}@DeleteMapping("/{id}")public Result<Void> del(@PathVariable Long id){s.delete(id);return Result.ok();}}
